-- creates the tables of the STAC Index website (stacindex.org)
-- Source: https://github.com/moregeo-it/stac-index/blob/master/database/create.sql
--
-- Column types are kept identical to the original schema so existing data
-- can be imported 1:1 (e.g. via pg_dump --data-only).
-- IDs use GENERATED BY DEFAULT so that imported rows can keep their original ids.
-- All statements are idempotent, so this script can also be run manually
-- against an existing database (see README.md).

-- Catalogs and APIs registered in the STAC Index
-- slug: Unique short name, used e.g. for stac_id generation by the crawler
-- access: Access type of the catalog (e.g. public, protected, private)
-- is_api: true for STAC APIs, false for static catalogs
CREATE TABLE IF NOT EXISTS catalogs (
    id INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    url TEXT UNIQUE NOT NULL,
    slug VARCHAR(50) UNIQUE NOT NULL,
    title TEXT NOT NULL,
    summary TEXT NOT NULL,
    email VARCHAR(255),
    access VARCHAR(10) NOT NULL,
    access_info TEXT,
    is_api BOOLEAN NOT NULL,
    created TIMESTAMP WITH TIME ZONE NOT NULL,
    updated TIMESTAMP WITH TIME ZONE NOT NULL
);

-- Ecosystem: Software and tools around STAC (libraries, clients, servers, ...)
CREATE TABLE IF NOT EXISTS ecosystem (
    id INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    url TEXT UNIQUE NOT NULL,
    title VARCHAR(75) NOT NULL,
    summary TEXT NOT NULL,
    categories VARCHAR(50)[] NOT NULL,
    email VARCHAR(255),
    created TIMESTAMP WITH TIME ZONE NOT NULL,
    updated TIMESTAMP WITH TIME ZONE NOT NULL,
    language VARCHAR(50)
);

-- Tutorials and learning resources about STAC
-- language: ISO 639-1 language code
CREATE TABLE IF NOT EXISTS tutorials (
    id INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    url TEXT NOT NULL,
    title VARCHAR(200) NOT NULL,
    summary TEXT NOT NULL,
    tags VARCHAR(50)[] NOT NULL,
    email VARCHAR(255),
    created TIMESTAMP WITH TIME ZONE NOT NULL,
    updated TIMESTAMP WITH TIME ZONE NOT NULL,
    language CHAR(2) NOT NULL
);
